\section{Introduction}

\subsection{The question}
Fix a semiprime $N=pq$ with $p,q$ distinct odd primes. All information about $p$
and $q$ is contained in $N$, but computationally inaccessible. A recurring idea
in the search for structural attacks is to \emph{change the modulus}: instead of
studying $N$, study a nearby integer built from $N$.

Formally, fix $f \in \Z[X]$ and set $M=f(N)$; we call $M$ a \emph{derived
modulus} and $f$ its \emph{generating polynomial}. The family under
investigation is
\[
\Fam=\{\,X-1,\ X+1,\ X^2+1,\ X^2+X+1,\ 2X-1,\ 2X+1\,\}.
\]
For each $f\in\Fam$ one computes an arithmetic invariant $C(M)$ -- least prime
factor, number of prime factors, a class number, a Jacobi-symbol statistic --
and asks whether $C(f(N))$ carries information about $(p,q)$ beyond what $N$
already determines.

\subsection{The confound, and the honest coordinate}
An empirical study must avoid a specific trap. For balanced semiprimes
$p\approx q\approx\sqrt{N}$, so any statistic tracking the magnitude of $N$ will
\emph{appear} correlated with $p$ and $p+q$ across a batch of varying size. This
is a confound. The factorisation-specific coordinate is the gap $|p-q|$, which
varies within the fibre of semiprimes of a given size.

Empirically the invariants correlate with $N$ at levels $0.66$--$0.95$, while
their correlation with $|p-q|$ remains inside the permutation null everywhere
examined: in a residual control with $n=40$, observed correlations were at most
$0.26$ against a $95$th null percentile of $0.29$--$0.31$. Several invariants
were moreover found to be degenerate. This paper proves that all of these
observations are forced.

\subsection{The physical framing}
The organising framing is a \emph{superselection rule}. Read $N$ as the
\emph{state} of a system and $f$ as an \emph{apparatus} producing an observable
$f(N)$. Because $f$ respects congruences, the observable lies in the algebra
generated by $N$, and cannot resolve the internal degeneracy of the state -- the
\emph{factorisation fibre}. Section~\ref{sec:spectrum} makes this precise: the
set of eigenvalues (primes) available to the observable is a property of the
apparatus alone.

\section{Definitions}

\begin{definition}[Derived modulus]
For $f\in\Z[X]$ and $N\in\Z$, the \emph{derived modulus} is $M=f(N)$.
\end{definition}

\begin{definition}[The tested family]
$\Fam$ consists of $f_0=X-1$, $f_1=X+1$, $f_2=X^2+1$, $f_3=X^2+X+1=\Phi_3(X)$,
$f_4=2X-1$, $f_5=2X+1$.
\end{definition}

\begin{definition}[Transparency]
$f\in\Z[X]$ is \emph{transparent} if $f(0)=1$ or $f(0)=-1$, i.e.\ $|f(0)|=1$.
\end{definition}

\begin{definition}[Congruence transport]
A map $F:\Z\to\Z$ \emph{transports congruences} if $(a-b)\mid(F(a)-F(b))$ for
all $a,b\in\Z$; equivalently $a\equiv b \pmod m$ implies
$F(a)\equiv F(b)\pmod m$ for every $m$.
\end{definition}

\begin{definition}[Prime support]
For $f\in\Z[X]$, $S_f=\{\,p \text{ prime}: \exists N\in\Z,\ p\mid f(N)\,\}$.
\end{definition}

\begin{definition}[Useful hint]
Given $N=pq$, an integer $h$ is a \emph{useful hint} if
$\gcd(N,h)\notin\{1,N\}$.
\end{definition}

\section{The frozen overlap and the classification}

\begin{lemma}[Difference divisibility]\label{lem:diff}
For every $f\in\Z[X]$ and all $a,b\in\Z$ we have $(a-b)\mid(f(a)-f(b))$. In
particular $N \mid f(N)-f(0)$.
\end{lemma}

\begin{proof}
Write $f=\sum_k c_kX^k$. Then $f(a)-f(b)=\sum_{k\ge 1}c_k(a^k-b^k)$ and
$a^k-b^k=(a-b)\sum_{j<k}a^jb^{k-1-j}$.
\end{proof}

\begin{theorem}[Frozen overlap]\label{thm:frozen}
For every $f\in\Z[X]$ and every $N\in\Z$,
\[
\gcd\bigl(N,f(N)\bigr)=\gcd\bigl(N,f(0)\bigr).
\]
\end{theorem}

\begin{proof}
Let $d=\gcd(N,f(N))$. Since $d\mid N$, Lemma~\ref{lem:diff} gives
$d\mid f(N)-f(0)$; with $d\mid f(N)$ this yields $d\mid f(0)$, so
$d\mid\gcd(N,f(0))$. Symmetrically $\gcd(N,f(0))$ divides $N$, hence
$f(N)-f(0)$, hence $f(N)$, hence $d$. Two-sided divisibility of non-negative
integers gives equality.
\end{proof}

\begin{corollary}\label{cor:unifbound}
$\gcd(N,f(N))$ divides $|f(0)|$ for every $N$. If $d\mid N$ and $d\mid f(N)$
then $d\mid f(0)$.
\end{corollary}

\begin{theorem}[Finitely many shared primes]
If $f(0)\ne 0$, the set of primes $p$ for which there exists $N$ with $p\mid N$
and $p\mid f(N)$ is finite; it is contained in the set of prime divisors of
$f(0)$.
\end{theorem}

\begin{theorem}[Classification of transparent moduli]\label{thm:class}
For $f\in\Z[X]$,
\[
\bigl(\forall N\in\Z:\ \gcd(N,f(N))=1\bigr)\iff f(0)=\pm 1 .
\]
\end{theorem}

\begin{proof}
($\Leftarrow$) By Corollary~\ref{cor:unifbound} the gcd divides $|f(0)|=1$.

($\Rightarrow$) Contrapositive; suppose $|f(0)|\ne 1$. If $f(0)=0$, take $N=2$:
Lemma~\ref{lem:diff} gives $2\mid f(2)-f(0)=f(2)$, so $\gcd(2,f(2))\ge 2$. If
$|f(0)|\ge 2$, let $r$ be the least prime factor of $|f(0)|$ and take $N=r$:
then $r\mid f(r)-f(0)$ and $r\mid f(0)$, so $r\mid f(r)$ and
$\gcd(r,f(r))\ge r>1$.
\end{proof}

\begin{remark}
This is a genuine classification, not a one-sided barrier. Moreover the
witnesses are the finitely many $N$ divisible by a prime factor of $f(0)$ -- a
list computable from $f$ alone, independent of any factorisation of $N$. Even
the leaks are uninformative.
\end{remark}

\begin{proposition}\label{prop:family}
Every $f\in\Fam$ has $f(0)=\pm 1$, hence $\gcd(N,f(N))=1$ for every integer $N$.
Explicit B\'ezout certificates:
\[
\begin{aligned}
1\cdot N+(-1)(N-1)&=1, & (-1)N+1\cdot(N+1)&=1,\\
(-N)N+1\cdot(N^2+1)&=1, & (-N-1)N+1\cdot(N^2+N+1)&=1,\\
2N+(-1)(2N-1)&=1, & (-2)N+1\cdot(2N+1)&=1.
\end{aligned}
\]
\end{proposition}

\begin{corollary}[Headline no-go]
If $p$ is prime, $f$ transparent and $p\mid N$, then $p\nmid f(N)$. For $N=pq$
neither prime factor divides any derived modulus of $\Fam$.
\end{corollary}

\subsection{Degeneracy of the empirical invariants}

\begin{proposition}\label{prop:degen}
Let $N$ be odd with $N\ge 3$. Then $\lpf(N+1)=\lpf(N-1)=2$; and
$N^2+1\equiv 2 \pmod 8$, so $\lpf(N^2+1)=2$ and the $2$-adic valuation of
$N^2+1$ is exactly $1$.
\end{proposition}

\begin{proof}
$N\pm 1$ is even and at least $2$. Writing $N=2k+1$, $N^2+1=4k(k+1)+2$ with
$k(k+1)$ even.
\end{proof}

Three of the six candidate invariants are therefore identically constant on the
odd inputs and carry zero bits; any measured correlation for them is an
artifact.

\subsection{Coarse-graining}

\begin{theorem}[Congruence transport for polynomials]\label{thm:coarse}
If $N\equiv N' \pmod m$ then $f(N)\equiv f(N') \pmod m$, for every $f\in\Z[X]$
and every $m$.
\end{theorem}

Consequently every residue-type invariant of a derived modulus is a function of
a residue of $N$: it coarse-grains $N$ and never refines it. This is the exact
arithmetic content of the empirical finding that $C(M)$ is a function of $N$.

\section{Closure: no combination escapes}

\subsection{The transparent monoid}

\begin{proposition}
$1$ is transparent, and if $f,g$ are transparent so is $fg$, since
$(fg)(0)=f(0)g(0)\in\{1,-1\}$. Hence the transparent polynomials form a
submonoid of $(\Z[X],\cdot)$, and finite products of transparent polynomials are
transparent.
\end{proposition}

\begin{proposition}[Substitution stability]
If $f$ is transparent and $g\in\Z[X]$ has $g(0)=0$, then $f\circ g$ is
transparent, since $(f\circ g)(0)=f(g(0))=f(0)$. Substitutions $N\mapsto 2N$,
$N\mapsto N^k$, $N\mapsto N^2+N$ all qualify.
\end{proposition}

\begin{proposition}[Composition law]
For all $f,g\in\Z[X]$ and all $N$,
$\gcd\bigl(N,f(g(N))\bigr)=\gcd\bigl(N,f(g(0))\bigr)$.
\end{proposition}

\begin{theorem}[The corner is closed]\label{thm:closure}
Let $L$ be a finite list of members of $\Fam$ (repetitions allowed),
$P=\prod_{f\in L}f$, and $g\in\Z[X]$ with $g(0)=0$. Then
$\gcd\bigl(N,(P\circ g)(N)\bigr)=1$ for every $N\in\Z$.
\end{theorem}

\begin{proof}
Each member of $\Fam$ is transparent; products and precompositions with $g$
preserve transparency; apply Theorem~\ref{thm:class}.
\end{proof}

\begin{corollary}
For every integer $N$,
\[
\gcd\Bigl(N,\ (N-1)(N+1)(N^2+1)(N^2+N+1)(2N-1)(2N+1)\Bigr)=1 .
\]
No product of the tested moduli, and no iterate such as $(2N)^2+1$, can expose a
factor of $N$.
\end{corollary}

\subsection{The resultant law}

\begin{theorem}[Resultant law]\label{thm:res}
Let $f,g\in\Z[X]$ with $\deg f\ne 0$ or $\deg g\ne 0$. Then for every $N\in\Z$,
\[
\gcd\bigl(f(N),g(N)\bigr)\ \big|\ \Res(f,g).
\]
\end{theorem}

\begin{proof}
The Sylvester--B\'ezout identity supplies $u,v\in\Z[X]$ with
$uf+vg=\Res(f,g)$ (a constant polynomial). Evaluating at $N$ gives
$u(N)f(N)+v(N)g(N)=\Res(f,g)$; any common divisor of $f(N)$ and $g(N)$ divides
the left-hand side.
\end{proof}

\begin{corollary}
If $\Res(f,g)\ne 0$ then $\gcd(f(N),g(N))\le|\Res(f,g)|$ for every $N$. For any
finite list of non-constant polynomials with pairwise nonzero resultants there
is a single constant $B$ bounding all pairwise overlaps for all $N$.
\end{corollary}

For the tested family the constants are minuscule; explicit certificates give,
for all $N$:

