\begin{theorem}[Uniform pairwise bound, with sharpness]
Any two distinct members of $\Fam$ satisfy $\gcd(f(N),g(N))\le 7$ for every $N$.
The bounds are attained: $\gcd(2^2+1,\,2\cdot 2+1)=5$ at $N=2$, and
$\gcd(4-1,\,4^2+4+1)=3$ at $N=4$; they cannot be improved to $1$.
\end{theorem}

Adding a second derived modulus contributes at most $O(1)$ new arithmetic,
uniformly in $N$, and that $O(1)$ is a fixed property of the polynomial pair.

\section{The spectrum belongs to the apparatus}\label{sec:spectrum}

\begin{theorem}[Order constraint, $X^2+1$]\label{thm:ord4}
Let $p$ be an odd prime with $p\mid N^2+1$ for some integer $N$. Then
$p\equiv 1 \pmod 4$.
\end{theorem}

\begin{proof}
Modulo $p$, $N^2\equiv -1$, so $N^4\equiv 1$ while $N^2\not\equiv 1$ (else
$p\mid 2$). Hence $\ord_p(N)=4$, and $4\mid p-1$ by Lagrange.
\end{proof}

\begin{theorem}[Order constraint, $\Phi_3$]\label{thm:ord3}
Let $p\ne 3$ be prime with $p\mid N^2+N+1$. Then $p\equiv 1 \pmod 3$.
\end{theorem}

\begin{proof}
$N^3-1=(N-1)(N^2+N+1)\equiv 0$, so $N^3\equiv 1$. If $N\equiv 1$ then
$N^2+N+1\equiv 3$, forcing $p=3$. So $\ord_p(N)=3$ and $3\mid p-1$.
\end{proof}

\begin{theorem}[Converses]
Every prime $p\equiv 1 \pmod 4$ divides $N^2+1$ for some $N$; every prime
$p\equiv 1 \pmod 3$ divides $N^2+N+1$ for some $N$.
\end{theorem}

\begin{proof}
$(\Z/p)^\times$ is cyclic of order $p-1$. If $4\mid p-1$, take $N$ of order $4$;
then $N^2$ has order $2$, so $N^2\equiv -1$. If $3\mid p-1$, take $N$ of order
$3$; then $(N-1)(N^2+N+1)\equiv 0$ with $N-1$ invertible.
\end{proof}

\begin{theorem}[Spectrum theorem]\label{thm:spectrum}
For a prime $p$,
\[
p\in S_{X^2+1}\iff p=2 \text{ or } p\equiv 1\!\!\pmod 4,
\qquad
p\in S_{X^2+X+1}\iff p=3 \text{ or } p\equiv 1\!\!\pmod 3 .
\]
These are precisely the primes that split in $\Q(i)$ and in $\Q(\zeta_3)$,
together with the ramified prime.
\end{theorem}

\begin{corollary}[$N$-independence of the spectrum]\label{cor:Nindep}
The set of primes available to the observable $N\mapsto N^2+1$ is one fixed
arithmetic progression, the same for every $N$, determined by the splitting
field of the generating polynomial. No feature of the spectrum can vary with the
factorisation of $N$.
\end{corollary}

\subsection{Congruence exclusion for cryptographic moduli}

\begin{theorem}[Blum rigidity]
If $p$ is prime with $p\equiv 3\pmod 4$, then $p\nmid M^2+1$ for
\emph{every} integer $M$.
\end{theorem}

\begin{corollary}[Double barrier]
Let $N=pq$ be a Blum integer, $p\equiv q\equiv 3\pmod 4$. Then $p\nmid N^2+1$
for two independent reasons: the gcd barrier of Theorem~\ref{thm:class}, and the
congruence exclusion above, which excludes $p$ from $M^2+1$ for \emph{all} $M$.
\end{corollary}

\begin{theorem}[Companion exclusion]
If $p\equiv 2\pmod 3$ is prime then $p\nmid M^2+M+1$ for every integer $M$.
\end{theorem}

Roughly half of all primes are excluded from each quadratic modulus purely by
congruence, and standard prime generation frequently \emph{selects} the excluded
half.

\section{Freshness: factoring the derived modulus does not help}

\begin{theorem}[Euclid step]\label{thm:euclid}
Let $f\in\Z[X]$ be non-constant with $f(0)=1$. For every finite set $S$ of
primes there exist $N$ and a prime $r\notin S$ with $r\mid f(N)$.
\end{theorem}

\begin{proof}
Choose $N$ a large multiple of $\prod_{s\in S}s$ with $|f(N)|>1$. For each
$s\in S$, $s\mid N$, so $f(N)\equiv f(0)=1 \pmod s$ and $s\nmid f(N)$. Any prime
factor of $f(N)$ therefore lies outside $S$.
\end{proof}

\begin{corollary}
For non-constant transparent $f$ the prime support $S_f$ is infinite: the primes
required to factor derived moduli exceed every bound.
\end{corollary}

\begin{theorem}[Freshness is useless]
If $f$ is transparent and $r$ is a prime with $r\mid f(N)$, then $r\nmid N$.
\end{theorem}

\begin{proof}
Otherwise $r\mid\gcd(N,f(N))=1$.
\end{proof}

\begin{corollary}
The prime support of $N^2+1$ is infinite -- factoring it is a fresh
factorisation problem of unbounded difficulty -- and no prime in that support
ever divides the corresponding $N$, so the fresh problem's answer is guaranteed
irrelevant.
\end{corollary}

\section{The natural generality of the barrier, and its boundary}

\subsection{Congruence transport}

\begin{theorem}[Abstract barrier]
If $F:\Z\to\Z$ transports congruences, then $\gcd(N,F(N))=\gcd(N,F(0))$ for
every $N$.
\end{theorem}

\begin{theorem}[Abstract classification]
For a congruence-transporting $F$,
$\bigl(\forall N:\gcd(N,F(N))=1\bigr)\iff F(0)=\pm 1$.
\end{theorem}

\begin{proof}
If $|F(0)|=1$ the gcd divides $1$. Conversely, taking $N=0$ gives
$\gcd(0,F(0))=|F(0)|=1$.
\end{proof}

\begin{theorem}[Algebraic structure]
The congruence-transporting maps contain all constants and the identity, are
closed under $+$, $-$ and $\cdot$ (hence form a subring of $\Z^{\Z}$), and are
closed under composition.
\end{theorem}

\begin{proof}
For products use $F(a)G(a)-F(b)G(b)=(F(a)-F(b))G(a)+F(b)(G(a)-G(b))$; for
composition, $a-b \mid G(a)-G(b) \mid F(G(a))-F(G(b))$.
\end{proof}

\subsection{The exponential modulus is outside the class -- and leaks}

\begin{theorem}[Outside the class]
$F(N)=2^N-1$ does not transport congruences: with $a=6$, $b=0$ we have
$a-b=6$ and $F(6)-F(0)=63$, and $6\nmid 63$.
\end{theorem}

\begin{theorem}[Leak criterion]\label{thm:leak}
For an odd prime $p$, $p\mid 2^N-1$ if and only if $\ord_p(2)\mid N$. Hence if
$p\mid N$ and $\ord_p(2)\mid N$, then $p\mid\gcd(N,2^N-1)$.
\end{theorem}

\begin{theorem}[Infinitely many leaks]
For every $k\ge 1$, $3\mid\gcd\bigl(6(k+1),\,2^{6(k+1)}-1\bigr)$. Hence
$\{N:\gcd(N,2^N-1)>1\}$ is infinite, in sharp contrast to the polynomial case
where only finitely many primes can ever be shared.
\end{theorem}

\begin{theorem}[A complete factorisation]
$\gcd\bigl(253,\ 2^{253}-1\bigr)=23$ and $253=11\cdot 23$.
\end{theorem}

\begin{proof}
$\ord_{23}(2)=11$ since $2^{11}-1=2047=23\cdot 89$ and $11$ is prime; as
$11\mid 253$, Theorem~\ref{thm:leak} gives $23\mid 2^{253}-1$. Conversely
$\ord_{11}(2)=10\nmid 253$, so $11\nmid 2^{253}-1$. The gcd divides $253$ and is
divisible by $23$ but not $11$, hence equals $23$.
\end{proof}

\begin{remark}
The leak condition $\ord_p(2)\mid N$ depends on the \emph{value} of $N$, not on
a residue, which is exactly why no polynomial construction can imitate it. This
is not a factoring algorithm: the leaky $N$ form a sparse set, and this is
recognisably the mechanism of the classical $p-1$ method, defeated in practice
by requiring $p-1$ to have a large prime factor.
\end{remark}

\section{The hint frontier}

\begin{theorem}[Four outcomes]
For $N=pq$ with $p,q$ distinct primes and any $h$,
$\gcd(N,h)\in\{1,p,q,N\}$. Moreover $\gcd(pq,h)=p$ if and only if $p\mid h$ and
$q\nmid h$; in that case $q=N/\gcd(N,h)$, so one useful hint yields the complete
factorisation.
\end{theorem}

\begin{theorem}[Exact count]
For distinct primes $p,q$,
\[
\#\{\,h\in\{0,1,\ldots,pq-1\}:\gcd(pq,h)\ne 1\,\}=p+q-1 .
\]
\end{theorem}

\begin{proof}
The complementary count is $\varphi(pq)=(p-1)(q-1)$ and
$pq-(p-1)(q-1)=p+q-1$.
\end{proof}

\begin{theorem}[Density of the frontier]
If $p,q>B\ge 1$ are distinct primes then $\dfrac{p+q-1}{pq}\le\dfrac{2}{B}$.
\end{theorem}

\begin{theorem}[Derived hints are always useless]
For every semiprime $N=pq$ and every $f\in\Fam$, $\gcd(N,|f(N)|)=1$; in
particular $\gcd(N,|f(N)|)\ne p$.
\end{theorem}

Useful hints exist and are exactly characterised, they are rare, and derived
moduli provably never produce one. Any future progress must come from
\emph{hint amplification} -- an external source of a number sharing a prime with
$N$.

\section{Algorithms}

\begin{enumerate}[label=\textbf{(\Alph*)}]
\item \emph{Frozen-overlap verification.} Compare $\gcd(N,f(N))$ with
$\gcd(N,f(0))$ over a range of $N$; they agree always. Cost
$O(R(\deg f+\log^2 N))$ over $R$ values.
\item \emph{Transparency classification and witness search.} Test $|f(0)|=1$; if
not transparent, output $N=2$ (when $f(0)=0$) or $N=\lpf(|f(0)|)$ and verify
$\gcd(N,f(N))>1$.
\item \emph{Resultant certification.} Build the Sylvester matrix of $f,g$ and
compute its determinant by fraction-free elimination, in
$O((\deg f+\deg g)^3)$ ring operations; the result bounds $\gcd(f(N),g(N))$ for
all $N$.
\item \emph{Spectrum membership test.} Decide $p\in S_{X^2+1}$ by
$p=2\ \vee\ p\equiv 1 \bmod 4$ in $O(1)$, with no knowledge of $N$.
\item \emph{Exponential-leak scan.} Compute $\gcd(N,\,2^N-1\bmod N)$ by fast
modular exponentiation in $O(\log^3 N)$ and report nontrivial values.
\item \emph{Hint-frontier census.} Enumerate $h<N$ and count $\gcd(N,h)\ne 1$,
verifying the value $p+q-1$.
\end{enumerate}

\section{Discussion}

Negative results in this area are usually heuristic barriers. What is unusual
here is that the obstruction is an \emph{exact classification}: universal
invisibility holds precisely when the constant term is a unit; the witnesses in
the failure case are explicit and factorisation-independent; the invisible class
is closed under exactly the operations an attacker has available; and the
boundary of the whole argument is located by a construction just outside it that
provably leaks.

Interpreting $N$ as a state and $f$ as an apparatus, the results assemble into a
superselection rule with three layers: an \emph{algebra} layer
(Theorem~\ref{thm:frozen}: the overlap is a constant of the apparatus), a
\emph{coarse-graining} layer (Theorem~\ref{thm:coarse}: residue observables
factor through residues of $N$), and a \emph{spectrum} layer
(Corollary~\ref{cor:Nindep}: the available eigenvalues are fixed by the
apparatus's splitting field). The factorisation fibre is a superselection
sector.

Limitations should be stated plainly. The barrier concerns invariants computed
from $N$ by congruence-transporting maps; attacks using additional structure --
lattice reduction on partially known bits, side channels, quantum
period-finding -- lie outside the hypothesis. The empirical component is a
statistical finding on finite batches; the theorems concern divisibility,
congruences and spectra, and establish that any invariant which is a function of
residues of $f(N)$, of divisibility relations between $N$ and $f(N)$, or of the
prime spectrum of $f$, cannot carry factor-specific information. The exponential
leak is a boundary marker, not an attack.

\section{Future directions}

\begin{conjecture}[Galois superselection]
For irreducible $f\in\Z[X]$ with splitting field $K_f$ and Galois group $G$, the
spectrum $S_f$ equals, up to finitely many primes, the set of $p$ whose
Frobenius class in $G$ fixes at least one root of $f$; and $p\in S_f$ is
decidable from $p$ alone. Consequently no invariant of $f(N)$ distinguishes two
semiprimes with the same $N$.
\end{conjecture}

The two spectra proved here are the abelian, cyclotomic shadow of a general
Frobenius criterion. The natural next target is the non-abelian case, e.g.
$f=X^3-X-1$ with $G=S_3$. The conjecture would be falsified by any $f$ whose
spectrum depends on more than the residue class of $p$.

\begin{conjecture}[Sharp resultant law]
The divisibility half is proved (Theorem~\ref{thm:res}). Open: for coprime
$f,g\in\Z[X]$, characterise exactly which divisors of $\Res(f,g)$ are attained
as $\gcd(f(N),g(N))$, and with what density in $N$. Sharpness examples ($5$ at
$N=2$; $3$ at $N=4$) suggest the attained set is governed by local solvability
modulo the prime powers dividing the resultant.
\end{conjecture}

\begin{conjecture}[Hint amplification]
Given external numbers with a known weak correlation to a factor of $N$, how
many independent such hints are needed before a useful one appears? The density
bound $2/B$ gives the base rate; the question is whether structured hint
distributions can beat it, and by how much, under explicit hardness assumptions.
\end{conjecture}

\begin{conjecture}[Beyond congruence transport]
Classify maps failing congruence transport in a controlled way -- transport on a
fixed congruence class, or transport modulo a fixed conductor. The exponential
modulus is the canonical example; a systematic theory would explain which
almost-transporting constructions can leak, and at what density.
\end{conjecture}

\begin{conjecture}[Degeneracy-corrected invariants]
Three of the six tested invariants are provably constant
(Proposition~\ref{prop:degen}). Re-run the analysis with corrected invariants
such as $\lpf\bigl((N^2+1)/2\bigr)$. The prediction from
Corollary~\ref{cor:Nindep} is that they remain inside the permutation null; a
violation would falsify the superselection reading.
\end{conjecture}

\section{Conclusion}

The identity $N\mid f(N)-f(0)$ freezes the entire overlap between a semiprime
and any polynomial derived modulus at the constant term; universal invisibility
is exactly the condition $f(0)=\pm 1$; the invisible class is a monoid closed
under products and substitution; pairwise interactions are bounded by
resultants, uniformly in $N$; the prime spectra of the quadratic moduli are
fixed sets of split primes; the prime support is infinite but never touches $N$;
the whole argument runs at the level of congruence-transporting maps; and just
outside that class the exponential modulus $2^N-1$ leaks, factoring
$253=11\cdot 23$ outright. The only escape is external information, whose useful
fraction is at most $2/B$.

A function of $N$ is a function of $N$. Coarse-graining never refines.

